  Ltac fold_xnp H :=
    change (nth (S (length (@nil Z)) mod length ((@nil Z) ++ h :: rest)) ((@nil Z) ++ h :: rest) 0) with xn in H;
    change (nth ((length (@nil Z) + length ((@nil Z) ++ h :: rest) - 1) mod length ((@nil Z) ++ h :: rest)) ((@nil Z) ++ h :: rest) 0) with xp in H.

